$existingLower = $mb.EmailAddresses | ForEach-Object { $_.ToString().ToLower() }
$actuallyNew = @()
foreach ($a in $toAdd) {
    if ($existingLower -notcontains $a.ToLower()) {
        $actuallyNew += $a
    }
}
Write-Host "New aliases to add: $($actuallyNew.Count)"

if ($actuallyNew.Count -gt 0) {
    $added = 0
    $failed = 0
    for ($i = 0; $i -lt $actuallyNew.Count; $i += 50) {
        $end = [Math]::Min($i + 49, $actuallyNew.Count - 1)
        $batch = $actuallyNew[$i..$end]
        try {
            Set-Mailbox -Identity "pricing@flashcargoglobal.com" -EmailAddresses @{Add=$batch} -ErrorAction Stop
            $added += $batch.Count
            Write-Host "  Batch $([Math]::Floor($i/50)+1): added $($batch.Count) (total: $added)"
        } catch {
            Write-Host "  Batch failed: $_"
            foreach ($a in $batch) {
                try {
                    Set-Mailbox -Identity "pricing@flashcargoglobal.com" -EmailAddresses @{Add=$a} -ErrorAction Stop
                    $added++
                } catch {
                    Write-Host "    SKIP: $a - $_"
                    $failed++
                }
            }
        }
    }
    Write-Host "Done: Added=$added Failed=$failed"
}

$mb2 = Get-Mailbox -Identity "pricing@flashcargoglobal.com"
Write-Host "Final aliases: $($mb2.EmailAddresses.Count)"
$mb2.EmailAddresses | Sort-Object | ForEach-Object { Write-Host "  $_" }

